use crate::myw::Gap;
use crate::util::open_url;
use leptos::prelude::*;
#[component]
pub fn MayiwenLogo() -> impl IntoView {
    let open_new_window = move |_| {
        open_url("https://mayiwen.com");
    };
    view! {
        <div style="text-align: center">
            <img on:click=open_new_window 
                src="data:image/png;base64,"
            />

        </div>
    }
}
